<?php
declare(strict_types=1);
require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/youtube-store.php';require_once __DIR__.'/noa-bridge/world-core.php';
header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');
function nwe(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$acts=[];$selected=null;$tracks=[];$videos=[];$error=false;$genre=is_string($_GET['genre']??null)?$_GET['genre']:'kpop-original';$id=is_string($_GET['act']??null)?$_GET['act']:'';$missing=false;
try{
 $db=noa_bridge_pdo();$batch=ny_batch($db);
 $q=$db->prepare('SELECT a.act_id,a.genre_id,a.act_number,p.owner_id,v.public_verified,v.fields_json FROM noa_catalog_acts a JOIN noa_catalog_playlists p ON p.playlist_id=a.act_id JOIN noa_catalog_versions v ON v.entity_id=a.act_id AND v.entity_type=\'playlist\' WHERE v.batch_id=? ORDER BY a.genre_id,a.act_number,a.act_id');$q->execute([$batch]);
 foreach($q as $row){if(!nw_public($row))continue;$row['fields']=json_decode($row['fields_json'],true,512,JSON_THROW_ON_ERROR);$acts[$row['act_id']]=$row;}
 if($id!==''){
  if(!preg_match('/^[a-f0-9]{64}$/D',$id)||!isset($acts[$id])){$missing=true;http_response_code(404);}
  else{
   $selected=$acts[$id];$genre=$selected['genre_id'];
   $q=$db->prepare('SELECT t.variant_id,t.position,t.song_id,t.status,t.raw_json,s.ep,v.public_verified,v.fields_json FROM noa_catalog_tracks t LEFT JOIN noa_catalog_songs s ON s.song_id=t.song_id LEFT JOIN noa_catalog_versions v ON v.batch_id=t.batch_id AND v.entity_id=t.song_id AND v.entity_type=\'song\' WHERE t.batch_id=? AND t.playlist_id=? ORDER BY t.variant_id,t.position');$q->execute([$batch,$id]);
   foreach($q as $row){$row['fields']=!empty($row['public_verified'])?json_decode($row['fields_json'],true,512,JSON_THROW_ON_ERROR):[];$tracks[]=$row;}
   $run=ny_latest($db);if($run){$bySong=[];foreach($tracks as $t)if(!empty($t['public_verified']))$bySong[$t['song_id']]=$t;foreach(ny_videos($db,$run) as $v){$song=$v['match']['songId']??'';if(nw_video($v)&&isset($bySong[$song])){$v['ep']=$bySong[$song]['ep'];$videos[$v['id']]=$v;}}uasort($videos,fn($a,$b)=>(int)$a['ep']<=>(int)$b['ep']?:strcmp($a['id'],$b['id']));}
  }
 }
}catch(Throwable $e){$error=true;http_response_code(503);error_log('[noa-world] '.get_class($e));}
