<?php if(!$selected):?><section class="noa-world noa-world-cast" aria-label="공식 캐릭터"><article class="noa-character"><img class="noa-world-face" src="/noa-assets/characters/noa-face.jpg" alt="NOA 공식 캐릭터" width="240" height="300"><div><p class="noa-eyebrow">FEMALE VOCAL</p><h2>NOA · 노아</h2><p>상처를 지나 자신의 빛을 찾아가는 목소리. 쉽게 마음을 열지 못하지만, 조금씩 다가오는 온기를 마주합니다.</p><a href="/noa-assets/characters/noa-sheet.png">공식 캐릭터시트 보기</a></div></article><article class="noa-character"><img class="noa-world-face" src="/noa-assets/characters/noel-face.jpg" alt="NOEL 공식 캐릭터" width="240" height="300"><div><p class="noa-eyebrow">MALE VOCAL</p><h2>NOEL · 노엘</h2><p>노아의 노래에 또 하나의 시선과 목소리를 더합니다. 서로 다른 마음이 솔로와 듀엣의 장면으로 이어집니다.</p><a href="/noa-assets/characters/noel-sheet.png">공식 캐릭터시트 보기</a></div></article></section><?php endif;?>
<form method="get" class="noa-world-filter"><label>장르별 이야기 <select name="genre" aria-label="세계관 장르"><?php foreach(array_unique(array_column($acts,'genre_id')) as $g):?><option value="<?=nwe($g)?>" <?=$genre===$g?'selected':''?>><?=nwe(strtoupper(str_replace('-',' ',$g)))?></option><?php endforeach;?></select></label><button type="submit" class="noa-button">보기</button></form>
<nav class="noa-world-links" aria-label="ACT 빠른 전환"><?php foreach($acts as $a):if($a['genre_id']!==$genre)continue;?><a href="/noa-world.php?act=<?=nwe($a['act_id'])?>" <?=$id===$a['act_id']?'aria-current="page"':''?>>ACT.<?=(int)$a['act_number']?></a><?php endforeach;?></nav>
<?php if(!$selected):?><section class="noa-world-grid" aria-label="ACT 이야기 목록"><?php foreach($acts as $a):if($a['genre_id']!==$genre)continue;?><a class="noa-world-act" href="/noa-world.php?act=<?=nwe($a['act_id'])?>"><span class="noa-eyebrow">ACT.<?=(int)$a['act_number']?></span><h2><?=nwe(nw_text($a['fields'],'title')?:'ACT.'.$a['act_number'])?></h2><span>이야기와 공식 MV 보기 →</span></a><?php endforeach;?></section>
<?php else:$f=$selected['fields'];?><header class="noa-world-heading"><p class="noa-eyebrow"><?=nwe(strtoupper(str_replace('-',' ',$genre)))?> / ACT.<?=(int)$selected['act_number']?></p><h2><?=nwe(nw_text($f,'title')?:'ACT.'.$selected['act_number'])?></h2></header>
<section class="noa-world-prose"><h2>프롤로그</h2><div class="noa-world-text"><?=nwe(nw_text($f,'worldPrologue')?:'이 ACT의 공식 소설 원문은 아직 연결되지 않았습니다.')?></div></section>
<section class="noa-world-prose" aria-label="EP별 챕터"><h2>Chapters</h2><?php $variant='';foreach($tracks as $t):if($variant!==$t['variant_id']):$variant=$t['variant_id'];?><p class="noa-muted">원본 수록 목록 · <?=nwe(substr($variant,0,12))?></p><?php endif;if(empty($t['public_verified'])):?><p>수록곡 정보 공개 확인 대기</p><?php continue;endif;$tf=$t['fields'];?><article class="noa-world-chapter"><p class="noa-eyebrow">EP.<?=nwe((string)$t['ep'])?></p><h3><?=nwe(nw_text($tf,'title')?:'제목 확인 중')?></h3><div class="noa-world-text"><?=nwe(nw_text($tf,'worldChapter')?:'공식 챕터 원문 연결 대기')?></div><a href="/noa-catalog.php?id=<?=nwe($t['song_id'])?>">곡 정보 보기</a></article><?php endforeach;?></section>
<section class="noa-world-prose"><h2>에필로그</h2><div class="noa-world-text"><?=nwe(nw_text($f,'worldEpilogue')?:'이 ACT의 공식 에필로그는 아직 연결되지 않았습니다.')?></div></section>
<section id="yt-player" hidden><h2 id="yt-playing"></h2><iframe id="yt-frame" title="NOA WORLD 공식 YouTube 플레이어" allow="autoplay; encrypted-media; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></section>
<section class="noa-world-prose"><h2>공식 MV · EP 순서</h2><?php if(!$videos):?><p class="noa-muted">이 ACT에 연결된 공개 공식 MV를 준비하고 있습니다.</p><?php endif;?><div class="yt-grid"><?php foreach($videos as $v):?><article class="yt-card"><button class="yt-watch" data-video="<?=nwe($v['id'])?>" data-title="<?=nwe($v['snippet']['title'])?>" aria-label="<?=nwe($v['snippet']['title'].' 재생')?>"><img loading="lazy" src="/noa-bridge/youtube-thumbnail.php?id=<?=nwe($v['id'])?>" alt=""><span class="yt-play" aria-hidden="true">▶</span></button><h3>EP.<?=nwe((string)$v['ep'])?> · <?=nwe($v['snippet']['title'])?></h3><details><summary>MV 설명 펼치기</summary><p class="noa-world-text"><?=nwe($v['snippet']['description']??'등록된 설명이 없습니다.')?></p></details></article><?php endforeach;?></div></section>
<?php endif;?><section class="noa-world-prose"><h2>별무리의 이야기</h2><a class="noa-button" href="/bbs/board.php?bo_table=free&amp;sfl=wr_subject%7C%7Cwr_content&amp;stx=NOA+WORLD">세계관 커뮤니티 소식</a><a class="noa-button" href="/noa-youtube.php?world=1">공식 MV 전체 보기</a></section><?php endif;?>
